    ax.plot(x, [OUT["AO_zeroshot_assistant"][best][h]["auroc"] for h in H], marker="s", ls="--", label=f"off-the-shelf AO ({best})")
for nm, lab, src in [("direct", "trained direct AO-style reader", "qa"), ("forecast", "forecast repr. (timing head)", "head")]:
